# rate_limiter.py — fix pool assignment
from connections import redis_critical  # Was redis_background

class SlidingWindowRateLimiter:
    def __init__(self, redis_conn=None):
        self.redis = redis_conn or redis_critical

async def confirm_payment(self, request):
    payment_id = request.data['payment_id']
    idempotency_key = request.headers.get('Idempotency-Key')

    if not idempotency_key:
        return Response({'error': 'Idempotency-Key header required'}, status=400)

    try:
        result = await self._execute_confirmation(payment_id, idempotency_key)
        return Response(result.to_dict(), status=200)
    except Payment.DoesNotExist:
        return Response({'error': 'Payment not found'}, status=404)
    except RateLimitExceeded:
        return Response({'error': 'Rate limit exceeded'}, status=429)

# health.py — pool metrics endpoint
