    return {
        "critical_pool": {
            "in_use": REDIS_POOL_CRITICAL._in_use_connections,
            "available": REDIS_POOL_CRITICAL.pool_size,
            "max": REDIS_POOL_CRITICAL.max_connections,
        },
        "locks_pool": {
            "in_use": REDIS_POOL_LOCKS._in_use_connections,
            "available": REDIS_POOL_LOCKS.pool_size,
            "max": REDIS_POOL_LOCKS.max_connections,
        },
        "background_pool": {
            "in_use": REDIS_POOL_BACKGROUND._in_use_connections,
